<script setup lang="ts">
import {computed,ref} from 'vue';import {Plus,Search,X,ArrowUpRight,Users} from 'lucide-vue-next';import {useWorkspace} from '../stores/workspace';import {useSession} from '../stores/session';import Avatar from '../components/Avatar.vue';import Notice from '../components/Notice.vue';import {date} from '../utils/format';import type {Customer} from '../types'
const w=useWorkspace(),s=useSession(),search=ref(''),filter=ref('all'),show=ref(false),selected=ref<Customer|null>(null),name=ref(''),external=ref(''),error=ref(''),busy=ref(false);const canCreate=computed(()=>['owner','admin'].includes(s.tenant?.role||''));const filtered=computed(()=>w.customers.filter(c=>(`${c.name||''} ${c.external_id}`).toLowerCase().includes(search.value.toLowerCase())&&(filter.value==='all'||(filter.value==='named'?!!c.name:!c.name))))
async function save(){busy.value=true;error.value='';try{await w.addCustomer(name.value.trim(),external.value.trim());show.value=false;name.value='';external.value=''}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="page-heading"><div><div class="eyebrow">RELACIONES QUE IMPORTAN</div><h1>Tus clientes, más cerca.</h1><p>Conoce a las personas con las que conversas.</p></div><button v-if="canCreate" class="button primary" @click="show=true;error='' "><Plus :size="18"/>Nuevo cliente</button></div><Notice v-if="s.mode==='demo'">Clientes de ejemplo. Los registros que crees son temporales y se reinician al recargar.</Notice><Notice v-if="w.error" error>{{w.error}} <button @click="w.load">Reintentar</button></Notice><section class="card"><div class="card-heading"><h2>Directorio de clientes <span class="count-badge">{{w.customers.length}}</span></h2><div class="toolbar"><label class="search-field"><Search :size="17"/><input v-model="search" aria-label="Buscar clientes" placeholder="Buscar nombre o identificador…"></label><select v-model="filter" aria-label="Filtrar clientes"><option value="all">Todos los clientes</option><option value="named">Con nombre</option><option value="unnamed">Sin nombre</option></select></div></div><div v-if="w.loading" class="loading" role="status">Cargando clientes…</div><div v-else class="table-scroll"><table><thead><tr><th>CLIENTE</th><th>IDENTIFICADOR EXTERNO</th><th>FECHA DE REGISTRO</th><th></th></tr></thead><tbody><tr v-for="c in filtered" :key="c.id"><td><button class="person plain" @click="selected=c"><Avatar :name="c.name||'Sin nombre'" :index="c.id"/><span><strong>{{c.name||'Sin nombre'}}</strong><small>Cliente #{{c.id}}</small></span></button></td><td><code>{{c.external_id}}</code></td><td class="muted">{{date(c.created_at)}}</td><td><button class="icon-button" :aria-label="`Ver ${c.name||c.external_id}`" @click="selected=c"><ArrowUpRight :size="18"/></button></td></tr></tbody></table><div v-if="!filtered.length" class="empty"><Users/><h3>No encontramos clientes</h3><p>Prueba otra búsqueda o registra tu primer cliente.</p></div></div><div class="table-footer">{{filtered.length}} clientes · Organización: {{s.tenant?.organization}}</div></section>
<dialog v-modal :open="show" v-if="show" class="modal" aria-labelledby="new-customer" @keydown.esc="!busy&&(show=false)"><form @submit.prevent="save"><div class="card-heading"><h2 id="new-customer">Nuevo cliente</h2><button type="button" class="icon-button" aria-label="Cerrar" :disabled="busy" @click="show=false"><X :size="20"/></button></div><Notice v-if="error" error>{{error}}</Notice><label>Nombre (opcional)<input v-model="name" autofocus maxlength="150" placeholder="Nombre del cliente"></label><label>Identificador externo<input v-model="external" required maxlength="150" pattern=".*\S.*" placeholder="Identificador único en esta organización"></label><p class="caption">{{s.mode==='demo'?'Se guardará solo en esta demostración.':'Disponible para administradores y propietarios.'}}</p><button class="button primary full" :disabled="busy">{{busy?'Guardando…':'Registrar cliente'}}</button></form></dialog>
<dialog v-modal v-if="selected" open class="modal" aria-labelledby="customer-title" @keydown.esc="selected=null"><div class="card-heading"><h2 id="customer-title">Información del cliente</h2><button class="icon-button" aria-label="Cerrar" @click="selected=null"><X :size="20"/></button></div><div class="customer-profile"><Avatar :name="selected.name||'Sin nombre'" :index="selected.id"/><h2>{{selected.name||'Sin nombre'}}</h2><code>{{selected.external_id}}</code></div><dl><dt>Cliente</dt><dd>#{{selected.id}}</dd><dt>Registrado</dt><dd>{{date(selected.created_at)}}</dd><dt>Organización</dt><dd>{{s.tenant?.organization}}</dd></dl><h3>Conversaciones</h3><div><RouterLink v-for="c in w.conversations.filter(c=>c.customer_id===selected?.id)" :key="c.id" :to="`/conversations?id=${c.id}`" class="detail-link">Conversación #{{c.id}} · {{c.channel}} <ArrowUpRight :size="16"/></RouterLink><p v-if="!w.conversations.some(c=>c.customer_id===selected?.id)" class="caption">Sin conversaciones.</p></div></dialog></template>
